"use client";

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { ElegantBackground } from '@/components/ui/elegant-background';
import { searchCertificate, Certificate } from '@/app/certificate-portal/actions';
import { CertificateDisplay } from '@/components/certificate-display';

interface CertificatePortalClientProps {
  initialCertificate?: any;
  initialId?: string;
}

export function CertificatePortalClient({ initialCertificate, initialId }: CertificatePortalClientProps) {
  const [query, setQuery] = useState(initialId || '');
  const [result, setResult] = useState<any | null>(initialCertificate || null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [recentSearches, setRecentSearches] = useState<string[]>([]);

  useEffect(() => {
    const saved = localStorage.getItem('recent_certificate_searches');
    if (saved) {
      setRecentSearches(JSON.parse(saved));
    }
  }, []);

  const addToRecent = (term: string) => {
    const updated = [term, ...recentSearches.filter(s => s !== term)].slice(0, 5);
    setRecentSearches(updated);
    localStorage.setItem('recent_certificate_searches', JSON.stringify(updated));
  };

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setError('');
    setResult(null);
    
    // Update URL without navigation
    window.history.pushState({}, '', `/certificate-portal/${query.trim()}`);

    try {
      const response = await searchCertificate(query.trim());
      if (response.success && response.data && response.data.length > 0) {
        setResult(response.data[0]);
        addToRecent(query.trim());
      } else {
        setError(response.error || 'No certificate found with this ID');
      }
    } catch (err) {
      setError('An error occurred while searching');
    } finally {
      setLoading(false);
    }
  };

  const clearRecent = () => {
    setRecentSearches([]);
    localStorage.removeItem('recent_certificate_searches');
  };

  return (
    <div className="min-h-screen relative overflow-hidden">
      <ElegantBackground variant="section" />
      
      <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <h1 className="font-[family-name:var(--font-cinzel)] text-4xl md:text-5xl font-bold text-foreground mb-4">
            Certificate <span className="text-accent-gold">Portal</span>
          </h1>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
            Verify and view IGACMUN certificates. Enter your Certificate ID below.
          </p>
        </motion.div>

        {/* Search Section */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="max-w-2xl mx-auto mb-16"
        >
          <form onSubmit={handleSearch} className="relative flex items-center">
            <div className="relative w-full group">
              <div className="absolute inset-0 bg-accent-gold/20 rounded-lg blur-md group-hover:blur-lg transition-all duration-300 opacity-50" />
              <input
                type="text"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Enter Certificate ID (e.g. 123456)"
                className="w-full bg-forest-900/80 border border-accent-gold/30 text-foreground placeholder:text-muted-foreground/50 rounded-lg py-4 pl-12 pr-32 focus:outline-none focus:border-accent-gold/60 focus:ring-1 focus:ring-accent-gold/60 transition-all backdrop-blur-sm relative z-10 font-mono"
              />
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-accent-gold/70 h-5 w-5 z-20" />
              
              <div className="absolute right-2 top-1/2 transform -translate-y-1/2 z-20">
                <Button 
                  type="submit" 
                  disabled={loading}
                  className="bg-accent-gold/10 hover:bg-accent-gold/20 text-accent-gold border border-accent-gold/30"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Verify'}
                </Button>
              </div>
            </div>
          </form>

          {/* Recent Searches */}
          {!result && recentSearches.length > 0 && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="mt-4 flex flex-wrap items-center justify-center gap-2"
            >
              <span className="text-xs text-muted-foreground mr-2">Recent:</span>
              {recentSearches.map((term) => (
                <button
                  key={term}
                  onClick={() => {
                    setQuery(term);
                    // We can trigger search immediately or just fill input
                    // Let's just fill input for now to let user confirm
                  }}
                  className="text-xs px-3 py-1 rounded-full bg-forest-900/50 border border-accent-gold/20 text-accent-gold/80 hover:bg-accent-gold/10 hover:text-accent-gold transition-colors font-mono"
                >
                  {term}
                </button>
              ))}
              <button
                onClick={clearRecent}
                className="text-xs text-muted-foreground hover:text-destructive ml-2 transition-colors"
              >
                Clear
              </button>
            </motion.div>
          )}
        </motion.div>

        {/* Results Section */}
        <div className="w-full">
          <AnimatePresence mode="wait">
            {loading ? (
              <motion.div
                key="loading"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="flex justify-center py-12"
              >
                <div className="flex flex-col items-center gap-4">
                  <div className="relative">
                    <div className="w-12 h-12 border-4 border-accent-gold/20 border-t-accent-gold rounded-full animate-spin" />
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-2 h-2 bg-accent-gold rounded-full animate-pulse" />
                    </div>
                  </div>
                  <p className="text-accent-gold/70 font-medium animate-pulse">Verifying ID...</p>
                </div>
              </motion.div>
            ) : error ? (
              <motion.div
                key="error"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                className="text-center py-12"
              >
                <div className="bg-destructive/10 border border-destructive/30 rounded-lg p-6 max-w-md mx-auto backdrop-blur-sm">
                  <p className="text-destructive font-medium">{error}</p>
                  <Button 
                    variant="link" 
                    onClick={() => setError('')}
                    className="text-destructive/70 mt-2"
                  >
                    Try Again
                  </Button>
                </div>
              </motion.div>
            ) : result ? (
              <CertificateDisplay 
                certificate={result} 
                valid={result.status !== 'revoked'}
                revoked={result.status === 'revoked'}
                revokedInfo={result.status === 'revoked' ? {
                  revoked_at: result.revoked_at,
                  revoked_reason: result.revoked_reason
                } : null}
              />
            ) : null}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}
