"use client";

import { motion } from "framer-motion";
import { Award, Calendar, Hash, School, Globe, Users, Download, Share2, CheckCircle, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { formatDateReadable } from "@/lib/utils";

type CertificateData = {
  certificate_id: string;
  participant_name: string;
  school: string;
  certificate_type: string;
  event: string | null;
  event_code: string | null;
  date_issued: string;
  status: string;
  pdf_available: boolean;
  pdf_download_url: string | null;
  country?: string;
  committee?: string;
  segment?: string;
  team_name?: string;
  level?: string;
  [key: string]: any;
};

interface CertificateDisplayProps {
  certificate: CertificateData;
  valid?: boolean;
  revoked?: boolean;
  revokedInfo?: {
    revoked_at: string;
    revoked_reason: string;
  } | null;
}

export function CertificateDisplay({ certificate, valid = true, revoked = false, revokedInfo }: CertificateDisplayProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
      className="w-full max-w-3xl mx-auto"
    >
        {/* Status Banner */}
        <div className={`mb-6 p-4 rounded-lg border flex items-center gap-3 backdrop-blur-sm ${
            revoked 
                ? "bg-destructive/10 border-destructive/30 text-destructive" 
                : valid 
                    ? "bg-green-500/10 border-green-500/30 text-green-400" 
                    : "bg-yellow-500/10 border-yellow-500/30 text-yellow-400"
        }`}>
            {revoked ? <AlertTriangle className="h-5 w-5" /> : <CheckCircle className="h-5 w-5" />}
            <div>
                <p className="font-semibold">
                    {revoked ? "Certificate Revoked" : valid ? "Official Certificate Verified" : "Verification Pending"}
                </p>
                {revoked && revokedInfo && (
                    <p className="text-sm opacity-90 mt-1">
                        Revoked on {formatDateReadable(revokedInfo.revoked_at)}: {revokedInfo.revoked_reason}
                    </p>
                )}
            </div>
        </div>

        {/* Main Info Card */}
        <div className="bg-forest-900/40 border border-accent-gold/20 rounded-xl overflow-hidden backdrop-blur-md shadow-xl">
            {/* Header Section */}
            <div className="p-8 border-b border-accent-gold/10 text-center md:text-left relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none">
                    <Award className="w-40 h-40" />
                </div>
                
                <div className="relative z-10">
                    <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-accent-gold/10 border border-accent-gold/20 text-accent-gold text-xs font-medium tracking-wider uppercase mb-4">
                        <Award className="w-3 h-3" />
                        {certificate.certificate_type}
                    </div>
                    
                    <h2 className="font-[family-name:var(--font-cinzel)] text-3xl md:text-4xl font-bold text-white mb-4 leading-tight">
                        {certificate.participant_name}
                    </h2>
                    
                    <div className="flex flex-wrap gap-y-2 gap-x-6 text-sm text-muted-foreground">
                        {certificate.school && (
                            <div className="flex items-center gap-2">
                                <School className="h-4 w-4 text-accent-gold/70" />
                                {certificate.school}
                            </div>
                        )}
                        {certificate.country && (
                            <div className="flex items-center gap-2">
                                <Globe className="h-4 w-4 text-accent-gold/70" />
                                {certificate.country}
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Details Grid */}
            <div className="p-8 grid gap-8 md:grid-cols-2">
                <div className="space-y-6">
                    <div>
                        <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3 flex items-center gap-2">
                            <Calendar className="h-3 w-3 text-accent-gold" /> Event Details
                        </h3>
                        <div className="bg-forest-950/30 rounded-lg p-4 border border-white/5 hover:border-accent-gold/10 transition-colors">
                            <p className="font-semibold text-foreground text-lg">{certificate.event || "IGACMUN Session III"}</p>
                            <p className="text-sm text-muted-foreground mt-1">Issued: {formatDateReadable(certificate.date_issued)}</p>
                            {certificate.event_code && (
                                <p className="text-xs text-accent-gold/60 mt-2 font-mono">Code: {certificate.event_code}</p>
                            )}
                        </div>
                    </div>

                    <div>
                        <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3 flex items-center gap-2">
                            <Hash className="h-3 w-3 text-accent-gold" /> Verification ID
                        </h3>
                        <div className="bg-forest-950/30 rounded-lg p-4 border border-white/5 flex items-center justify-between group hover:border-accent-gold/10 transition-colors">
                            <code className="text-accent-gold font-mono text-lg tracking-wide">{certificate.certificate_id}</code>
                        </div>
                    </div>
                </div>

                <div className="space-y-6">
                    <div>
                        <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3 flex items-center gap-2">
                            <Users className="h-3 w-3 text-accent-gold" /> Participation Info
                        </h3>
                        <div className="bg-forest-950/30 rounded-lg p-4 border border-white/5 space-y-3 hover:border-accent-gold/10 transition-colors">
                            {certificate.committee ? (
                                <div className="flex justify-between items-center border-b border-white/5 pb-2 last:border-0 last:pb-0">
                                    <span className="text-sm text-muted-foreground">Committee</span>
                                    <span className="text-sm font-medium text-foreground text-right">{certificate.committee}</span>
                                </div>
                            ) : (
                                <div className="flex justify-between items-center border-b border-white/5 pb-2 last:border-0 last:pb-0">
                                    <span className="text-sm text-muted-foreground">Role</span>
                                    <span className="text-sm font-medium text-foreground text-right">Delegate</span>
                                </div>
                            )}
                            
                            {certificate.level && (
                                <div className="flex justify-between items-center border-b border-white/5 pb-2 last:border-0 last:pb-0">
                                    <span className="text-sm text-muted-foreground">Level</span>
                                    <span className="text-sm font-medium text-foreground text-right capitalize">{certificate.level}</span>
                                </div>
                            )}
                            {certificate.segment && (
                                <div className="flex justify-between items-center border-b border-white/5 pb-2 last:border-0 last:pb-0">
                                    <span className="text-sm text-muted-foreground">Segment</span>
                                    <span className="text-sm font-medium text-foreground text-right">{certificate.segment}</span>
                                </div>
                            )}
                             {certificate.team_name && (
                                <div className="flex justify-between items-center border-b border-white/5 pb-2 last:border-0 last:pb-0">
                                    <span className="text-sm text-muted-foreground">Team</span>
                                    <span className="text-sm font-medium text-foreground text-right">{certificate.team_name}</span>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Actions Footer */}
            <div className="p-6 bg-forest-950/40 border-t border-white/5 flex flex-col sm:flex-row gap-4 justify-end">
                 <Button
                  onClick={() => {
                    navigator.clipboard.writeText(
                      `${window.location.origin}/certificate-portal/${certificate.certificate_id}`
                    );
                    alert("Link copied!");
                  }}
                  variant="outline"
                  className="border-accent-gold/20 hover:bg-accent-gold/10 text-accent-gold"
                >
                  <Share2 className="h-4 w-4 mr-2" />
                  Share Verification
                </Button>
                
                {certificate.pdf_available && certificate.pdf_download_url && (
                  <Button
                    onClick={() => window.open(certificate.pdf_download_url!, "_blank")}
                    className="bg-accent-gold hover:bg-accent-gold/90 text-forest-950"
                  >
                    <Download className="h-4 w-4 mr-2" />
                    Download Original PDF
                  </Button>
                )}
            </div>
        </div>
    </motion.div>
  );
}
